<!DOCTYPE html>
<html>
<head>
<title>Conway's Game of Life</title>
<style>
body {
  background-color: #1e1e1e;
  display: flex;
  flex-direction: column;
  align-items: center;
}

#life {
  border: 2px solid #333;
  margin: 20px;
  display: grid;
  grid-template-columns: repeat(40, 15px);
  grid-template-rows: repeat(40, 15px);
}

.live {
  background-color: #2a9d8f;
}

#controls {
  margin-top: 20px;
  display: flex;
  justify-content: center;
}

button {
  padding: 10px 20px;
  font-size: 16px;
  background-color: #333;
  color: #fff;
  border: none;
  cursor: pointer;
  margin: 5px;
}

button:hover {
  background-color: #444;
}
</style>
</head>
<body>
  <h1>Conway's Game of Life</h1>
  <canvas id="life"></canvas>
  <div id="controls">
    <button id="step">Step</button>
    <button id="play">Play</button>
    <button id="random">Randomize</button>
    <button id="clear">Clear</button>
  </div>

<script>
const w = 40;
const h = 40;
const cellSize = 15;
const grid = document.getElementById('life');

let life = {
  w,
  h,
  get(x, y) {
    if (x < 0 || x >= w || y < 0 || y >= h) return 0;
    return grid.getContext('2d').getImageData(x * cellSize, y * cellSize, cellSize, cellSize).data[0];
  },
  set(x, y, v) {
    if (v === 1) {
      grid.getContext('2d').fillStyle = '#2a9d8f';
    } else {
      grid.getContext('2d').fillStyle = 'none';
    }
    grid.getContext('2d').fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
  },
  step() {
    const nextGrid = Array(w).fill(null).map(() => Array(h).fill(0));

    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        let liveNeighbors = 0;
        for (let i = -1; i <= 1; i++) {
          for (let j = -1; j <= 1; j++) {
            if (i === 0 && j === 0) continue;
            const neighborX = x + i;
            const neighborY = y + j;

            if (neighborX >= 0 && neighborX < w && neighborY >= 0 && neighborY < h) {
              liveNeighbors += life.get(neighborX, neighborY);
            }
          }
        }

        nextGrid[y][x] = (life.get(x, y) === 1) ? 1 : (liveNeighbors === 3 ? 1 : 0);
      }
    }

    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        life.set(x, y, nextGrid[y][x]);
      }
    }
  },
  clear() {
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        life.set(x, y, 0);
      }
    }
  }
};

document.getElementById('step').addEventListener('click', life.step);
document.getElementById('play').addEventListener('click', () => {
  let running = true;
  const intervalId = setInterval(life.step, 100);

  return () => {
    running = false;
    clearInterval(intervalId);
  };
});

document.getElementById('random').addEventListener('click', life.clear);
document.getElementById('clear').addEventListener('click', life.clear);

grid.addEventListener('click', (event) => {
  const x = Math.floor(event.offsetX / cellSize);
  const y = Math.floor(event.offsetY / cellSize);
  life.set(x, y, !life.get(x, y));
});

grid.addEventListener('mousedown', (event) => {
    const x = Math.floor(event.offsetX / cellSize);
    const y = Math.floor(event.offsetY / cellSize);
    life.set(x, y, true);
  });

grid.addEventListener('mouseup', (event) => {
    const x = Math.floor(event.offsetX / cellSize);
    const y = Math.floor(event.offsetY / cellSize);
    life.set(x, y, false);
  });
</script>
</body>
</html>
